<?php
header('Access-Control-Allow-Origin: *');header('Access-Control-Allow-Methods: GET, OPTIONS');header('Access-Control-Allow-Headers: Content-Type, Authorization');header('Content-Type: application/json');if($_SERVER['REQUEST_METHOD']==='OPTIONS'){exit;}
require_once __DIR__.'/../includes/db.php';require_once __DIR__.'/../includes/rut.php';require_once __DIR__.'/../includes/modulos_clinica.php';
try{$pdo=getDB();asegurarModulosClinica($pdo);$rut=normalizarRut(trim((string)($_GET['rut']??'')));$id=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT m.id FROM mascotas m JOIN duenos d ON d.id=m.dueno_id WHERE m.id=:id AND d.rut=:rut');$q->execute([':id'=>$id,':rut'=>$rut]);if(!$q->fetchColumn()){http_response_code(404);echo json_encode(['success'=>false,'message'=>'Mascota no encontrada']);exit;}$q=$pdo->prepare('SELECT token FROM carnets_mascotas WHERE mascota_id=:id');$q->execute([':id'=>$id]);$token=$q->fetchColumn();if(!$token){$token=bin2hex(random_bytes(32));$pdo->prepare('INSERT INTO carnets_mascotas (mascota_id,token) VALUES (:id,:token)')->execute([':id'=>$id,':token'=>$token]);}$scheme=(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')?'https':'http';$base=rtrim(dirname(dirname($_SERVER['SCRIPT_NAME'])),'/');$url=$scheme.'://'.$_SERVER['HTTP_HOST'].$base.'/carnet_mascota.php?token='.$token;echo json_encode(['success'=>true,'token'=>$token,'url'=>$url]);}catch(Throwable $e){error_log('API carnet: '.$e->getMessage());http_response_code(500);echo json_encode(['success'=>false,'message'=>'Error del servidor']);}
